MATCH (s:Set {set_num: '10785-1'})-[:HAS_INVENTORY]->(i:Inventory)
WITH s, i
ORDER BY i.version DESC
LIMIT 1
WITH s, i

// Get direct parts from set's own inventory (non-spare)
OPTIONAL MATCH (i)-[hp:HAS_PART {is_spare: false}]->(p:Part)
WITH s, i, COALESCE(SUM(hp.qty), 0) AS direct_parts

// Get all nested items (sets and minifigs) with their quantities
// We need to recursively explode nested sets and minifigs

// First, let's get all paths from this inventory to parts through nested items
// Using variable-length path for nesting

// Get nested sets and minifigs at any level, tracking quantity multipliers
// We'll use a recursive approach with path binding

// Start with the initial inventory
UNWIND [0] AS dummy
WITH s, i, direct_parts

// Collect all inventory nodes we need to traverse from, with accumulated quantities
// Start with the root inventory at quantity 1
CALL {
    WITH i
    UNWIND [{inv: i, qty: 1}] AS start
    WITH start
    // Variable length traversal through inventories via nested sets/minifigs
    MATCH p = (start.inv)-[:CONTAINS_SET|CONTAINS_MINIFIG*0..]->(inv:Inventory)
    WHERE start.inv = i OR ALL(r IN relationships(p) WHERE r.qty IS NOT NULL)
    WITH inv, 
         CASE WHEN length(p) = 0 THEN 1 
              ELSE reduce(acc = start.qty, r IN relationships(p) | acc * r.qty) 
         END AS path_qty
    RETURN inv, SUM(path_qty) AS total_qty
}

WITH s, i, direct_parts, collect({inv: inv, qty: total_qty}) AS inventory_list

// For each inventory in the list, get its parts (non-spare)
UNWIND inventory_list AS item
WITH s, i, direct_parts, item.inv AS current_inv, item.qty AS multiplier

// Get parts from this inventory
OPTIONAL MATCH (current_inv)-[hp:HAS_PART {is_spare: false}]->(p:Part)
WITH s, i, direct_parts, current_inv, multiplier, COALESCE(SUM(hp.qty * multiplier), 0) AS contributed_parts

// Sum all parts from all inventories
WITH s, i, direct_parts, SUM(contributed_parts) AS total_parts

// Calculate percentage from nested items
WITH s, i, direct_parts, total_parts, 
     (total_parts - direct_parts) AS nested_contribution

RETURN CASE WHEN total_parts = 0 THEN 0.00 
            ELSE round(100.0 * nested_contribution / total_parts, 2) 
       END AS percentage_from_nested
