  // All edges must be from current inventory (highest version for that parent)
  AND ALL(r IN relationships(path) WHERE r.version = [
    MATCH (parent)-[check:CONTAINS]->()
    WHERE parent = startNode(r)
    RETURN max(check.version) AS maxVer
  ][0])
}
