MATCH (set:Set)
WHERE EXISTS {
  // Find all paths from set's current inventory to the target part
  MATCH (set)-[:HAS_INVENTORY]->(inv:Inventory)
  WITH set, inv
  ORDER BY inv.version DESC
  WITH set, head(collect(inv)) AS currentInv

  // Match the recursive path through inventories to parts
  MATCH path = (currentInv)-[:CONTAINS_SET|CONTAINS_MINIFIG*0..]->(targetInv:Inventory)-[hp:HAS_PART]->(p:Part {part_num: '88064pr0003'})
  WHERE hp.is_spare = false OR hp.is_spare IS NULL

  // Ensure we follow HAS_INVENTORY from sets/minifigs to their inventories
  AND ALL(i IN range(0, length(path)-1) WHERE 
    i % 2 = 0 OR // even indices are :CONTAINS_SET or :CONTAINS_MINIFIG relationships
    EXISTS {
      MATCH (item)-[:HAS_INVENTORY]->(invNode) 
      WHERE id(invNode) = id(nodes(path)[i])
    }
  )
}
RETURN count(DISTINCT set) AS num_sets
