MATCH (s:Set {set_num: '45801-1'})
WITH s
CALL {
  WITH s
  // Get all part paths from set through nested sets and minifigs, excluding spare parts
  MATCH p = (s)-[:CONTAINS*1..]->(x)
  WHERE (x:Part OR x:Minifig) AND ALL(r IN relationships(p) WHERE r.is_spare = false OR r.is_spare IS NULL)
  WITH s, p, x, reduce(acc = 1, r IN relationships(p) | acc * r.qty) as total_qty
  WHERE x:Part
  RETURN sum(total_qty) as total_parts
}
CALL {
  WITH s
  // Get parts directly in set's inventory (not through nested sets/minifigs)
  MATCH (s)-[r:CONTAINS]->(p:Part)
  WHERE r.is_spare = false OR r.is_spare IS NULL
  RETURN sum(r.qty) as direct_parts
}
CALL {
  WITH s
  // Get parts from nested sets and minifigs
  MATCH p = (s)-[:CONTAINS*1..]->(x:Part)
  WHERE length(p) > 1 AND ALL(r IN relationships(p) WHERE r.is_spare = false OR r.is_spare IS NULL)
  WITH reduce(acc = 1, r IN relationships(p) | acc * r.qty) as total_qty
  RETURN sum(total_qty) as nested_parts
}
RETURN round(100.0 * nested_parts / total_parts, 2) as percentage
