MATCH (s:Set {set_num: '6051-1'})-[:HAS_INVENTORY]->(i:Inventory {version: 1})
CALL {
  WITH i
  UNWIND [0] AS dummy
  // Collect all parts from this inventory directly
  CALL {
    WITH i
    OPTIONAL MATCH (i)-[hp:HAS_PART]->(p:Part)
    WHERE hp.is_spare = false
    RETURN sum(hp.qty) AS direct_parts
  }
  // Collect parts from nested sets (recursively using their current inventory)
  CALL {
    WITH i
    OPTIONAL MATCH path = (i)-[:CONTAINS_SET*1..]->(nestedSet:Set)-[:HAS_INVENTORY]->(ni:Inventory)
    WITH path, nestedSet, ni
    WHERE ALL(r IN relationships(path) WHERE type(r) = 'CONTAINS_SET')
    WITH nestedSet, ni, reduce(acc = 1, r IN relationships(path) | acc * r.qty) AS path_qty
    // Get current inventory for nested set
    WITH nestedSet, path_qty, max(ni.version) AS max_version
    MATCH (nestedSet)-[:HAS_INVENTORY]->(ci:Inventory {version: max_version})
    OPTIONAL MATCH (ci)-[hp:HAS_PART]->(p:Part)
    WHERE hp.is_spare = false
    RETURN sum(hp.qty * path_qty) AS nested_set_parts
  }
  // Collect parts from minifigs (recursively using their current inventory)
  CALL {
    WITH i
    OPTIONAL MATCH (i)-[cm:CONTAINS_MINIFIG]->(mf:Minifig)-[:HAS_INVENTORY]->(mi:Inventory)
    WITH mf, mi, cm.qty AS mf_qty
    // Get current inventory for minifig
    WITH mf, mf_qty, max(mi.version) AS max_version
    MATCH (mf)-[:HAS_INVENTORY]->(cmi:Inventory {version: max_version})
    OPTIONAL MATCH (cmi)-[hp:HAS_PART]->(p:Part)
    WHERE hp.is_spare = false
    RETURN sum(hp.qty * mf_qty) AS minifig_parts
  }
  RETURN coalesce(direct_parts, 0) + coalesce(nested_set_parts, 0) + coalesce(minifig_parts, 0) AS total_parts
}
RETURN total_parts AS total_parts_count
